const body = $input.first().json.body;
const product = body.product;
const asset = product.asset;

if (!asset || !asset.assetBlobId) throw new Error("No GLB found for product " + product.uuid);

return [{
  json: {
    productUuid: product.uuid,
    productName: product.name,
    organizationUuid: body.organization.uuid,
    clientUuid: body.client.uuid,
    modelBlobId: asset.assetBlobId
  }
}];
